package com.crowdin.client.core.http.impl.json;

import com.fasterxml.jackson.core.JsonProcessingException;
import org.junit.Assert;
import org.junit.Test;

import java.util.Collections;
import java.util.List;

public class JacksonJsonTransformerTest {
    @Test
    public void parseValidJsonTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String jsonString = "[{\"id\":1,\"name\":\"Item 1\"},{\"id\":2,\"name\":\"Item 2\"}]";

        List<TestItem> items = transformer.parse(jsonString, List.class);

        Assert.assertEquals(2, items.size());
        Assert.assertEquals(1, items.get(0).getId());
        Assert.assertEquals("Item 1", items.get(0).getName());
        Assert.assertEquals(2, items.get(1).getId());
        Assert.assertEquals("Item 2", items.get(1).getName());
    }

    @Test(expected = CrowdinApiException.class)
    public void parseInvalidJsonTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String invalidJsonString = "[{\"id\":1,name:\"Item 1\"},{\"id\":2,\"name\":\"Item 2\"}]";

        transformer.parse(invalidJsonString, List.class);
    }

    @Test
    public void convertObjectToJsonStringTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        List<TestItem> items = Collections.singletonList(new TestItem(1, "Item 1"));

